const cfg = $input.first().json;
return String(cfg.item_types || '')
  .split(',').map(s => s.trim().toUpperCase()).filter(Boolean)
  .map(t => ({ json: { itemType: t } }));

const rows = $input.all();
const types = $('Parse Item Types').all().map(i => i.json.itemType);
const out = [];
for (let i = 0; i < rows.length; i++) {
  const r = rows[i].json || {};
  const status = r.statusCode;
  const body = r.body || {};
  const itemType = types[i] || 'UNKNOWN';
  if (status === 401 || status === 403) {
    throw new Error('Wix rejected the API key (HTTP ' + status + '). Check the key is valid, that it has View SEO Settings and Manage SEO Settings permissions, and that wix_site_id matches a site the key can reach.');
  }
  if (status === 428) {
    throw new Error('This site runs a different Wix Stores catalog version than the endpoint expects. Wix says: ' + JSON.stringify(body).slice(0, 200));
  }
  if (status !== 200) {
    throw new Error('Wix returned HTTP ' + status + ' for ' + itemType + ': ' + JSON.stringify(body).slice(0, 300));
  }
  out.push({ json: Object.assign({ __itemType: itemType }, body) });
}
return out;

const cfg = $('Set Wix Configuration').first().json;
const brand = String(cfg.brand_name || '').trim();
const maxItems = Number(cfg.max_items_per_run) || 20;
const skipNoindex = cfg.skip_noindex !== false && cfg.skip_noindex !== 'false';

const pick = (tags, fn) => (tags || []).map(t => t.tag).find(fn);
const out = [];
const skipped = { noindex: 0, alreadyWritten: 0, nothingMissing: 0 };
let scanned = 0;

for (const item of $input.all()) {
  const j = item.json;
  const itemType = j.__itemType;
  for (const rec of (j.itemSeoTags || [])) {
    scanned++;
    const rt = rec.resolvedTags || [];
    const titleTag = pick(rt, t => t.type === 'title');
    const descTag  = pick(rt, t => t.type === 'meta' && t.props && t.props.name === 'description');
    const ogDesc   = pick(rt, t => t.type === 'meta' && t.props && t.props.property === 'og:description');
    const canon    = pick(rt, t => t.type === 'link' && t.props && t.props.rel === 'canonical');
    const robots   = pick(rt, t => t.type === 'meta' && t.props && t.props.name === 'robots');

    const currentTitle = titleTag ? String(titleTag.children || '') : '';
    const currentDesc  = descTag && descTag.props ? String(descTag.props.content || '') : '';
    const ogText       = ogDesc && ogDesc.props ? String(ogDesc.props.content || '') : '';
    const url          = canon && canon.props ? String(canon.props.href || '') : '';
    const noindex      = robots && robots.props ? String(robots.props.content || '').includes('noindex') : false;

    // Pages Wix is told not to index are not worth spending AI quota on.
    if (noindex && skipNoindex) { skipped.noindex++; continue; }
    // Somebody already wrote these by hand. Leave their work alone.
    if (rec.hasOverride && currentDesc) { skipped.alreadyWritten++; continue; }

    const needsDesc  = !currentDesc;
    const needsTitle = !rec.hasOverride;
    if (!needsDesc && !needsTitle) { skipped.nothingMissing++; continue; }

    const slug = url ? String(url.split('?')[0].replace(/\/$/, '').split('/').pop() || '') : '';

    out.push({ json: {
      itemId: rec.itemId,
      itemType,
      url,
      slug: slug.replace(/[-_]+/g, ' '),
      currentTitle,
      currentDesc,
      sourceText: ogText,
      brand,
      needsTitle,
      needsDesc,
      // Carried so the write step can merge instead of overwrite.
      existingTags: rec.tags || []
    }});
  }
}

if (out.length === 0) return [{ json: { __none: true, scanned, skipped, skipNoindex } }];
if (out.length <= maxItems) return out;

// Take a fair share of each item type. A site with 200 static pages would otherwise
// use the whole batch on pages and never reach the products.
const buckets = {};
for (const o of out) (buckets[o.json.itemType] = buckets[o.json.itemType] || []).push(o);
const keys = Object.keys(buckets);
const picked = [];
let round = 0;
while (picked.length < maxItems) {
  let tookOne = false;
  for (const k of keys) {
    if (buckets[k][round]) {
      picked.push(buckets[k][round]);
      tookOne = true;
      if (picked.length >= maxItems) break;
    }
  }
  if (!tookOne) break;
  round++;
}
return picked;

const cfg = $('Set Wix Configuration').first().json;
const j = $input.first().json || {};
const s = j.skipped || {};
const notes = [];
if (s.noindex)        notes.push(s.noindex + ' item(s) are set to noindex, so they were skipped. A site that has never been published is entirely noindex. Set skip_noindex to false in Settings if you want to prepare tags before launch.');
if (s.alreadyWritten) notes.push(s.alreadyWritten + ' item(s) already have a custom title and description. This workflow never overwrites work somebody did by hand.');
if (s.nothingMissing) notes.push(s.nothingMissing + ' item(s) already had everything they needed.');
if (!notes.length)    notes.push('No items of the selected types were found. Check item_types in Settings, and that the API key can reach this site.');
return [{ json: {
  mode: 'No changes needed',
  site_id: cfg.wix_site_id,
  itemsScanned: j.scanned || 0,
  proposed: 0,
  written: 0,
  whyNothingHappened: notes
}}];

// One lookup for every product in this batch. Costs nothing when there are none.
const ids = $input.all().map(i => i.json.itemId).filter(Boolean);
const productIds = $input.all().filter(i => i.json.itemType === 'STORES_PRODUCT').map(i => i.json.itemId);
return [{ json: {
  search: {
    filter: productIds.length ? { id: { $in: productIds } } : { id: { $in: ['+1234567890+1234567890'] } },
    cursorPaging: { limit: 100 }
  },
  fields: ['DESCRIPTION', 'INFO_SECTION']
}}];

// Wix returns product copy as Ricos rich content. Flatten it to plain text.
const flat = (n) => {
  if (!n) return '';
  if (Array.isArray(n)) return n.map(flat).join(' ');
  if (typeof n === 'object') {
    if (n.textData && n.textData.text) return n.textData.text;
    return n.nodes ? flat(n.nodes) : '';
  }
  return '';
};

const res = $input.first().json || {};
const products = {};
if (res.statusCode === 200 && res.body && Array.isArray(res.body.products)) {
  for (const p of res.body.products) {
    const bits = [];
    const desc = flat((p.description || {}).nodes).trim();
    if (desc) bits.push(desc);
    for (const s of (p.infoSections || [])) {
      const t = flat((s.description || {}).nodes).trim();
      if (t) bits.push(s.title + ': ' + t);
    }
    const opts = (p.options || []).map(o => {
      const choices = ((o.choicesSettings || {}).choices || []).map(c => c.name).filter(Boolean);
      return choices.length ? o.name + ' (' + choices.join(', ') + ')' : o.name;
    }).filter(Boolean);
    if (opts.length) bits.push('Options: ' + opts.join('; '));
    const price = p.actualPriceRange && p.actualPriceRange.minValue ? p.actualPriceRange.minValue.formattedAmount : null;
    if (price) bits.push('Price from ' + price);
    products[p.id] = { name: p.name, text: bits.join('. ') };
  }
}

return $('Identify Missing Tags').all().map(row => {
  const j = Object.assign({}, row.json);
  const p = products[j.itemId];
  if (p) {
    j.productName = p.name;
    j.sourceText = [j.sourceText, p.text].filter(Boolean).join('. ');
  }
  return { json: j };
});

const cfg = $('Set Wix Configuration').first().json;
const items = $input.all().map(i => i.json);
const brand = String(cfg.brand_name || '').trim();
const titleMax = Number(cfg.title_max_chars) || 60;
const descMin = Number(cfg.desc_min_chars) || 120;
const descMax = Number(cfg.desc_max_chars) || 158;

const label = { STATIC_PAGE: 'website page', BLOG_POST: 'blog post', STORES_PRODUCT: 'product page' };

const lines = items.map((it, n) => {
  const bits = [];
  bits.push('itemId: ' + it.itemId);
  bits.push('this is a ' + (label[it.itemType] || it.itemType.toLowerCase()));
  if (it.productName) bits.push('product name: ' + it.productName);
  if (it.slug) bits.push('page slug: ' + it.slug);
  if (it.currentTitle) bits.push('current title tag: ' + it.currentTitle);
  if (it.sourceText) bits.push('page content: ' + String(it.sourceText).slice(0, 900));
  if (it.url) bits.push('url: ' + it.url);
  return '### Item ' + (n + 1) + '\n' + bits.join('\n');
}).join('\n\n');

const prompt = [
  'Write SEO title tags and meta descriptions for pages on a website' +
    (brand ? ' called "' + brand + '"' : '') + '.',
  '',
  'Rules:',
  '1. Title: at most ' + titleMax + ' characters INCLUDING any brand suffix. Lead with what the page is about, not the brand.',
  '2. Meta description: between ' + descMin + ' and ' + descMax + ' characters. Plain sentences that say what the visitor gets.',
  '3. Use only the information given. Never invent prices, shipping times, discounts, guarantees, locations, awards, review scores or stock levels.',
  '4. No clickbait, no ALL CAPS, no exclamation marks, no emoji, no quote marks wrapping the line.',
  '5. Every title and every description must differ from every other one in this batch.',
  '6. If the current title tag is already specific and useful, return it unchanged and focus on the description.',
  '7. Write in the same language as the source material.',
  '8. Return one object per item, reusing the exact itemId given.',
  '',
  'Items:',
  '',
  lines
].join('\n');

return [{ json: {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0.4,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          itemId: { type: 'STRING' },
          title: { type: 'STRING' },
          metaDescription: { type: 'STRING' }
        },
        required: ['itemId', 'title', 'metaDescription']
      }
    }
  }
}}];

const cfg = $('Set Wix Configuration').first().json;
const titleMax = Number(cfg.title_max_chars) || 60;
const descMin = Number(cfg.desc_min_chars) || 120;
const descMax = Number(cfg.desc_max_chars) || 158;

const gaps = {};
for (const g of $('Combine Product Data').all()) gaps[g.json.itemId] = g.json;

const raw = $input.first().json;
let parsed;
try { parsed = JSON.parse(raw.candidates[0].content.parts[0].text); }
catch (e) { throw new Error('Gemini did not return usable JSON. Response started: ' + JSON.stringify(raw).slice(0, 300)); }
if (!Array.isArray(parsed)) throw new Error('Expected a JSON array from Gemini, got ' + typeof parsed);

const clean = s => String(s == null ? '' : s).replace(/\s+/g, ' ').replace(/^["']|["']$/g, '').trim();
const seenTitles = new Set();
const seenDescs = new Set();
const accepted = [];
const rejected = [];

for (const row of parsed) {
  const gap = gaps[row.itemId];
  if (!gap) { rejected.push({ itemId: row.itemId, reason: 'returned an itemId that was not in this batch' }); continue; }

  const title = clean(row.title);
  const desc = clean(row.metaDescription);
  const curTitle = clean(gap.currentTitle);
  const curDesc = clean(gap.currentDesc);
  const why = [];

  if (!title) why.push('empty title');
  if (title.length > titleMax) why.push('title ' + title.length + ' chars, limit ' + titleMax);
  if (!desc) why.push('empty description');
  if (desc && desc.length < descMin) why.push('description ' + desc.length + ' chars, minimum ' + descMin);
  if (desc.length > descMax) why.push('description ' + desc.length + ' chars, maximum ' + descMax);
  if (/[!]|[\u{1F300}-\u{1FAFF}]/u.test(title + ' ' + desc)) why.push('contains an exclamation mark or emoji');
  if (title && title === title.toUpperCase() && title.length > 8) why.push('title is all caps');
  if (title && seenTitles.has(title.toLowerCase())) why.push('duplicate title within this batch');
  if (desc && seenDescs.has(desc.toLowerCase())) why.push('duplicate description within this batch');

  const titleChanged = title.toLowerCase() !== curTitle.toLowerCase();
  const descChanged  = desc.toLowerCase() !== curDesc.toLowerCase();
  if (!titleChanged && !descChanged) why.push('identical to what is already on the item, nothing to write');

  if (why.length) { rejected.push({ itemId: row.itemId, url: gap.url, title, desc, reason: why.join('; ') }); continue; }

  seenTitles.add(title.toLowerCase());
  seenDescs.add(desc.toLowerCase());
  accepted.push({
    itemId: row.itemId,
    itemType: gap.itemType,
    url: gap.url,
    beforeTitle: curTitle || '(none)',
    beforeDesc: curDesc || '(none)',
    title,
    metaDescription: desc,
    titleChanged,
    descriptionAdded: !curDesc,
    titleLen: title.length,
    descLen: desc.length,
    existingTags: gap.existingTags || []
  });
}

return [{ json: { accepted, rejected, acceptedCount: accepted.length, rejectedCount: rejected.length } }];

const cfg = $('Set Wix Configuration').first().json;
const accepted = $input.first().json.accepted || [];
const publishDrafted = cfg.publish_drafted_types === true || cfg.publish_drafted_types === 'true';
const BASE = 'https://www.wixapis.com/seo-metatags-server/v1/item-seo-tags/';

// Static pages and blog posts keep a draft and a published revision. Writing with
// publish:true targets the published revision, while the draft is what the editor and
// the read API show you, so the default is to write the draft.
const DRAFTED = ['STATIC_PAGE', 'BLOG_POST'];

// A write replaces the item's ENTIRE tag set. Anything already there that we are not
// changing (robots noindex on a cart page, a canonical override, custom og tags) has to
// be carried across or it is destroyed silently.
const mergeTags = (existing, title, desc) => {
  const keep = (existing || []).filter(t => {
    if (t.type === 'title') return false;
    if (t.type === 'meta' && t.props && t.props.name === 'description') return false;
    return true;
  });
  return keep.concat([
    { type: 'title', children: title },
    { type: 'meta', props: { name: 'description', content: desc }, children: '' }
  ]);
};

// One request per item. The bulk endpoint reports success for store products and then
// writes nothing, so every type goes through the single-item endpoint instead.
return accepted.map(r => {
  const body = {
    itemSeoTags: { tags: mergeTags(r.existingTags, r.title, r.metaDescription) },
    fieldMask: 'tags'
  };
  if (DRAFTED.includes(r.itemType)) {
    if (publishDrafted) body.publish = true;
  } else {
    body.publish = true;
  }
  return { json: {
    url: BASE + r.itemType + '/' + r.itemId,
    body,
    itemId: r.itemId,
    itemType: r.itemType,
    title: r.title
  }};
});

const cfg = $('Set Wix Configuration').first().json;
const v = $('Validate Generated Tags').first().json;
const dryRun = cfg.dry_run === true || cfg.dry_run === 'true';

let written = 0, failed = 0;
const apiErrors = [];
if (!dryRun) {
  const reqs = $('Construct Write Requests').all().map(i => i.json);
  const rows = $input.all();
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i].json || {};
    const req = reqs[i] || {};
    if (r.statusCode === 200) { written++; }
    else {
      failed++;
      apiErrors.push({ itemId: req.itemId, itemType: req.itemType, status: r.statusCode,
        description: JSON.stringify(r.body || {}).slice(0, 200) });
    }
  }
}

const notes = [];
if (dryRun) notes.push('Dry run. Nothing was sent to Wix. Set dry_run to false in Settings when the proposed tags look right.');
if (!dryRun && written) notes.push('Static page and blog post tags are written to the site draft. Publish the site in the Wix editor for them to go live.');
if (v.rejectedCount) notes.push(v.rejectedCount + ' suggestion(s) failed validation and were not written. See rejected below.');

return [{ json: {
  mode: dryRun ? 'DRY RUN - nothing written to Wix' : 'LIVE - tags written to Wix',
  site_id: cfg.wix_site_id,
  proposed: v.acceptedCount,
  written: dryRun ? 0 : written,
  writeFailures: dryRun ? 0 : failed,
  rejectedByValidator: v.rejectedCount,
  notes,
  changes: v.accepted,
  rejected: v.rejected,
  apiErrors
}}];
